INSERT INTO TBEP_ITEMSBAREMACION (BEPBLO_CODNUM,CODIGO,NOMBRE,DESCRIPCION,VALOR,VALOR_MINIMO,VALOR_MAXIMO,AFINIDAD) SELECT bepblo.CODNUM AS BEPBLO_CODNUM, '1' AS CODIGO, 'Nota media de las asignaturas cursadas en la titulación exigida para la plaza' AS NOMBRE, 'Ítem 1 DESCRIPCION' AS DESCRIPCION, 1 AS VALOR, 1 AS VALOR_MINIMO, 1000 AS VALOR_MAXIMO, 'AI' AS AFINIDAD FROM TBEP_BLOQUESBAREMACION bepblo ORDER BY bepblo.CODIGO FETCH FIRST 1 ROWS ONLY;
